        // Typed value round-trip through real XML serialization.
        const ExyokiOffice::StringValue sampleUri = ExyokiOffice::StringValue(std::string_view("eo-sample"));
        hosted.element->SetUri(sampleUri);
        CHECK(hosted.element->GetUri() == sampleUri);
        const ExyokiOffice::StringValue sampleManifestLocation = ExyokiOffice::StringValue(std::string_view("eo-sample"));
        hosted.element->SetManifestLocation(sampleManifestLocation);
        CHECK(hosted.element->GetManifestLocation() == sampleManifestLocation);
        const ExyokiOffice::StringValue sampleSchemaLocation = ExyokiOffice::StringValue(std::string_view("eo-sample"));
        hosted.element->SetSchemaLocation(sampleSchemaLocation);
        CHECK(hosted.element->GetSchemaLocation() == sampleSchemaLocation);
        const auto reloaded = hosted.RoundTrip();
        REQUIRE(reloaded.element != nullptr);
        CHECK(reloaded.element->GetUri() == sampleUri);
        CHECK(reloaded.element->GetManifestLocation() == sampleManifestLocation);
        CHECK(reloaded.element->GetSchemaLocation() == sampleSchemaLocation);
